INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','easy','flashcard','What are the three cell types of bone and their primary functions?','["Osteoblasts (bone formation/matrix synthesis), Osteoclasts (bone resorption), Osteocytes (mechanosensing; regulate remodelling via sclerostin and RANKL)"]','A','Osteoblasts derive from mesenchymal stem cells; osteoclasts from haematopoietic precursors (monocyte-macrophage lineage). Osteocytes are terminally differentiated osteoblasts embedded in lacunae.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','easy','flashcard','State Wolff''''s law.','["Bone adapts its architecture (both mass and structure) in response to the mechanical loads placed upon it — increased loading promotes bone deposition; disuse promotes resorption."]','A','Wolff''''s law underpins exercise prescription for osteoporosis prevention and explains adaptive changes in cortical bone thickness in loaded limbs (e.g., dominant arm of tennis players).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','medium','flashcard','Describe the RANK-RANKL-OPG axis in bone remodelling.','["RANKL (on osteoblasts/stromal cells) binds RANK (on osteoclast precursors) → osteoclastogenesis. OPG (osteoprotegerin, secreted by osteoblasts) acts as a decoy receptor for RANKL, inhibiting osteoclast formation."]','A','The balance between RANKL and OPG determines osteoclast activity. PTH and oestrogen withdrawal increase RANKL:OPG ratio. Denosumab is an anti-RANKL monoclonal antibody used in osteoporosis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','medium','flashcard','What is the organic and inorganic composition of bone matrix?','["~35% organic (mainly type I collagen + non-collagenous proteins: osteocalcin, osteopontin); ~65% inorganic (hydroxyapatite: Ca10(PO4)6(OH)2). Collagen provides tensile strength; hydroxyapatite provides compressive strength."]','A','Osteocalcin (secreted by osteoblasts, vitamin K-dependent) is a clinical marker of bone formation. Hydroxyapatite mineralisation is impaired in vitamin D deficiency, causing osteomalacia.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','medium','flashcard','Describe the structure of a Haversian system (osteon).','["Concentric lamellae of mineralised bone matrix surrounding a central Haversian canal (blood vessels, lymphatics, nerves). Osteocytes in lacunae communicate via canaliculi. Volkmann''''s canals connect adjacent Haversian canals perpendicularly."]','A','Haversian systems are the structural units of compact (cortical) bone. Cancellous (trabecular) bone has a honeycomb structure aligned along stress trajectories without true osteons.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','hard','flashcard','What is the sequence of the bone remodelling cycle?','["Activation (osteoclast recruitment by RANKL/M-CSF) → Resorption (~2-4 weeks) → Reversal (mononuclear cells) → Formation (osteoblasts deposit osteoid, ~3-4 months) → Mineralisation → Quiescence."]','A','Each remodelling cycle takes 3-6 months. In osteoporosis, resorption exceeds formation. Bisphosphonates suppress the resorption phase, preserving bone mass but potentially impairing targeted remodelling (atypical femoral fracture risk with prolonged use).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','hard','flashcard','How does intermittent PTH differ from continuous PTH in its effects on bone?','["Intermittent PTH (e.g., once-daily teriparatide) → anabolic: favours osteoblast survival and activity → net bone formation. Continuous PTH (as in primary hyperparathyroidism) → catabolic: prolonged RANKL stimulation → net bone resorption."]','A','Teriparatide (recombinant PTH 1-34) is the only anabolic agent for osteoporosis approved for severe cases. The mechanism exploits the anabolic window created by pulsatile PTH exposure, increasing osteoblast life span and number relative to the resorptive effect.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','medium','flashcard','Name four biochemical markers of bone turnover and specify whether they reflect formation or resorption.','["Formation: ALP (alkaline phosphatase), osteocalcin, P1NP (procollagen type I N-terminal propeptide). Resorption: NTX/CTX (N- and C-terminal cross-linked telopeptides of type I collagen), TRAP5b (tartrate-resistant acid phosphatase isoform 5b), urinary DPD (deoxypyridinoline)."]','A','These markers are used clinically to monitor treatment response in osteoporosis. P1NP and CTX are WHO-endorsed reference markers. ALP is elevated in Paget''''s disease and bone metastases.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','easy','flashcard','What is intramembranous ossification and where does it occur?','["Bone forms directly from mesenchymal (fibrous) tissue without a cartilage template. Osteoblasts differentiate from mesenchymal cells within fibrous membranes and deposit osteoid directly. Occurs in flat bones of the skull, mandible, and clavicle."]','A','Intramembranous ossification contrasts with endochondral ossification (bone formed by replacing a cartilage template), which occurs in long bones, vertebrae, and the base of the skull.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Structure & Remodelling','hard','flashcard','What is sclerostin and its clinical significance?','["Sclerostin (encoded by SOST) is secreted by osteocytes and inhibits Wnt/β-catenin signalling in osteoblasts, suppressing bone formation. Sclerosteosis/van Buchem disease = SOST loss-of-function mutations → excessive bone formation."]','A','Romosozumab (anti-sclerostin antibody) is approved for postmenopausal osteoporosis. By blocking sclerostin, it activates Wnt signalling, increasing osteoblast activity and decreasing osteoclast differentiation simultaneously (dual mechanism).','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','easy','flashcard','Name the three types of cartilage and give one anatomical location for each.','["1) Hyaline — articular surfaces, costal cartilages, tracheal rings; 2) Fibrocartilage — intervertebral discs, menisci, pubic symphysis; 3) Elastic — auricle, epiglottis, laryngeal cartilages (cuneiform, corniculate)."]','A','All cartilage is avascular and aneural (except fibrocartilage, which has limited vascularity). Nutrition is by diffusion. This explains the poor regenerative capacity of cartilage after injury.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','easy','flashcard','Which collagen types are associated with: (a) bone and tendon; (b) cartilage; (c) basement membranes?','["(a) Type I — bone, tendon, ligament, skin, cornea (most abundant collagen); (b) Type II — hyaline and elastic cartilage; (c) Type IV — basement membranes of all epithelial and endothelial cells."]','A','Collagen type III (reticular fibres) is found in loose connective tissue, liver, spleen, lymph nodes. Type X is associated with hypertrophic cartilage in the growth plate. Alport syndrome involves type IV collagen mutations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','medium','flashcard','What are the major glycosaminoglycans (GAGs) in articular cartilage and their structural role?','["Chondroitin sulphate and keratan sulphate are covalently attached to the aggrecan core protein, forming proteoglycans. These bind hyaluronic acid via link proteins to form large aggregates that are highly hydrophilic (fixed negative charges from sulphate groups attract water), providing compressive stiffness."]','A','GAG concentration declines with ageing and osteoarthritis, reducing the compressive resistance of cartilage. MRI T2 mapping and dGEMRIC can estimate GAG content non-invasively.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','medium','flashcard','What is the composition and function of the ground substance in connective tissue?','["Ground substance consists of proteoglycans (aggrecan, versican, decorin), glycoproteins (fibronectin, laminin), and water. It fills the space between cells and fibres, providing hydration, regulating diffusion of nutrients and signalling molecules, and contributing to tissue mechanical properties."]','A','The extracellular matrix (ECM) is not inert — it stores and presents growth factors (e.g., TGF-β, FGF bound to heparan sulphate proteoglycans). Fibronectin mediates cell adhesion to ECM via RGD sequence-integrin interactions.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','medium','flashcard','How does fibrocartilage differ structurally and mechanically from hyaline cartilage?','["Fibrocartilage: abundant type I collagen fibres (high tensile strength + shear resistance), less ground substance, no perichondrium, limited cellularity. Hyaline: type II collagen in fine meshwork, abundant proteoglycans (compressive resistance), perichondrium present (except articular surfaces)."]','A','Fibrocartilage is found where high tensile and shear forces occur (disc annulus, menisci). Its repair tissue after injury is fibrocartilage, not hyaline cartilage, explaining inferior long-term function of repaired menisci or articular cartilage.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','hard','flashcard','Describe the collagen cross-linking process and explain why it is important for tendon mechanical properties.','["Tropocollagen molecules (triple helix) are secreted, then lysyl oxidase (Cu2+-dependent enzyme) cross-links adjacent tropocollagen molecules by oxidising lysine/hydroxylysine residues to form pyridinium cross-links. These covalent intermolecular bonds dramatically increase tensile strength and stiffness of fibres."]','A','Copper deficiency, lathyrism (β-aminopropionitrile inhibits lysyl oxidase), and Menkes disease impair cross-linking, causing fragile connective tissue. Ageing increases cross-linking density, making tendons stiffer and more brittle.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','hard','flashcard','What molecular changes underlie the cartilage degradation in rheumatoid arthritis?','["Synovial macrophages and fibroblast-like synoviocytes secrete MMP-1, 3, 13 (collagenases/stromelysin) and ADAMTS-4/5 (aggrecanases), degrading type II collagen and aggrecan. TNF-α, IL-1β, and IL-6 from pannus drive MMP expression and inhibit matrix synthesis."]','A','ADAMTS-5 (aggrecanase-2) is the principal aggrecanase in murine models. Biologic therapies (anti-TNF, anti-IL-6) reduce MMP and ADAMTS expression, slowing cartilage destruction. TIMP (tissue inhibitors of metalloproteinases) normally counterbalances MMPs.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','easy','flashcard','What is appositional versus interstitial growth in cartilage?','["Appositional growth: new cartilage deposited on outer surface from chondroblasts in the inner perichondrium — increases width. Interstitial growth: chondrocytes divide within lacunae and secrete new matrix, expanding the cartilage from within — increases length."]','A','Interstitial growth occurs mainly in young, growing cartilage. Adult articular cartilage has limited regenerative capacity. Epiphyseal growth plates grow primarily by interstitial growth within the proliferating zone.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','hard','flashcard','What is Marfan syndrome and which structural protein is affected?','["Marfan syndrome is caused by mutations in FBN1 (fibrillin-1), a glycoprotein that forms microfibrils in the ECM. Fibrillin-1 sequesters TGF-β; deficiency leads to excess TGF-β signalling. Features: tall stature, arachnodactyly, lens dislocation, aortic root dilation, mitral valve prolapse."]','A','TGF-β antagonism with losartan (AT1R blocker, reduces TGF-β signalling) has shown benefit in Marfan mouse models and some clinical studies. Aortic dissection is the major cause of mortality, requiring prophylactic β-blockade and monitoring.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Cartilage & Connective Tissue','medium','flashcard','What enzyme deficiency causes scurvy, and how does this affect connective tissue?','["Scurvy is caused by vitamin C (ascorbic acid) deficiency. Ascorbate is an essential cofactor for prolyl and lysyl hydroxylases, which hydroxylate proline and lysine residues in procollagen — a prerequisite for triple-helix stability and cross-linking."]','A','Without hydroxylation, collagen triple helices are unstable, cannot be secreted properly, and form a weakened matrix. Clinical features: perifollicular haemorrhages, bleeding gums, poor wound healing, corkscrew hairs, and subperiosteal haemorrhage in children (Pelkan spurs on X-ray).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','easy','flashcard','Define the sarcomere and identify its boundaries.','["The sarcomere is the basic contractile unit of striated muscle, defined as the segment between two consecutive Z discs (Z lines). Average resting length ~2.0-2.4 µm. Contains interdigitating thick (myosin) and thin (actin) filaments."]','A','Sarcomere components: Z discs (α-actinin) → I band (actin only) → A band (myosin ± actin overlap) → H zone (myosin only) → M line (myomesin). A band length = myosin filament length = constant ~1.6 µm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','easy','flashcard','What is a motor unit and how does motor unit size relate to motor control precision?','["A motor unit = one α-motor neuron + all skeletal muscle fibres it innervates (all same fibre type). Small motor units (few fibres, e.g., extraocular muscles: 1:3 ratio) → fine motor control. Large motor units (many fibres, e.g., gastrocnemius: 1:2000 ratio) → coarse but powerful contractions."]','A','The size of the motor unit determines the minimum increment of force that can be added by recruiting one additional unit (force resolution). Fine motor tasks require small motor units; gross motor tasks tolerate large units.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','medium','flashcard','Describe the role of titin in the sarcomere.','["Titin spans from Z disc to M line (~1 µm in human cardiac, slightly longer in skeletal). Its elastic PEVK and immunoglobulin-like domain regions provide passive tension when stretched and centre the myosin filament. Acts as a molecular spring and scaffold, setting resting sarcomere length."]','A','Titin is the largest known protein (~3,000-4,200 kDa). Cardiac titin isoforms (N2B, shorter; N2BA, longer) regulate passive stiffness. Titin mutations cause dilated cardiomyopathy (DCM) — the most common genetic DCM mutation. Titin may also have a role in active force generation at long sarcomere lengths.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','medium','flashcard','What is the triad of skeletal muscle and what is its functional significance?','["A triad consists of one T-tubule flanked by two terminal cisternae of the sarcoplasmic reticulum (SR). Located at the A-I band junction in skeletal muscle. The triad is the structural basis for excitation-contraction (E-C) coupling: T-tubule action potentials activate DHPR, which mechanically opens RyR1 in the SR, releasing calcium."]','A','Cardiac muscle has dyads (one T-tubule + one SR terminal cisterna) at the Z line. The architecture of the triad ensures rapid and synchronous calcium release throughout the muscle fibre interior, enabling swift, uniform contraction.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','medium','flashcard','What are the components of the thin (actin) filament?','["F-actin backbone (double helix of G-actin monomers, each with one ADP + one myosin-binding site), tropomyosin (coiled-coil protein lying in the major groove of actin, covering myosin-binding sites at rest), and the troponin complex (TnT — anchors to tropomyosin; TnI — inhibitory; TnC — calcium binding)."]','A','There are approximately 7 actin monomers per tropomyosin molecule and one troponin complex per tropomyosin. Each tropomyosin covers 7 actin monomers. Troponin T attaches the complex to tropomyosin; TnI maintains inhibition; TnC is the calcium sensor (4 calcium binding sites).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','hard','flashcard','Describe the thick (myosin) filament structure in skeletal muscle.','["~200-300 myosin II molecules. Each has two globular heads (S1 — ATPase + actin binding site) on a long helical tail (S2 + LMM). Tails form the backbone; heads project outward in a helical pattern with a 14.3 nm repeat. Central bare zone (~150 nm) has no heads (tail-to-tail antiparallel arrangement). Total length ~1.6 µm."]','A','Each myosin head contains two heavy chains and four light chains (two essential + two regulatory). Regulatory light chain phosphorylation is critical for smooth muscle activation. In skeletal muscle, the heavy chain isoform (MHC I, IIa, IIx) determines fibre type and ATPase speed.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','hard','flashcard','What is nebulin and what happens when it is mutated?','["Nebulin (~800 kDa) is a giant protein extending along the length of each thin filament from the Z disc, acting as a molecular ruler that defines thin filament length (~1 µm in skeletal muscle). It also stabilises F-actin and may regulate cross-bridge cycling. Mutations → nemaline myopathy (most common cause)."]','A','Nemaline myopathy is characterised by nemaline rods (accumulations of Z-disc proteins — α-actinin and actin) on Gomori trichrome-stained muscle biopsy. Presents with hypotonia, proximal muscle weakness. Other causes: mutations in TPM2, TPM3, ACTA1, TNNT1.','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','easy','flashcard','What is the difference between the A band, I band, H zone, and M line in a sarcomere?','["A band (dark, anisotropic): full length of myosin including overlap with actin; constant during contraction. I band (light, isotropic): actin only; shortens during contraction. H zone: central A band region with myosin only (no actin); disappears in maximal contraction. M line: centre of A band; cross-links between myosin filaments via myomesin."]','A','During contraction: I band and H zone shorten/disappear; A band length constant; sarcomere length decreases. This is the basis of the sliding filament theory (Huxley, 1954).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','medium','flashcard','What is the sarcoplasmic reticulum (SR) and how is it organised relative to the myofibrils?','["The SR is a specialised smooth ER network surrounding each myofibril. Terminal cisternae (lateral sacs) are the calcium reservoirs flanking each T-tubule. The longitudinal SR connects the terminal cisternae along the fibre and contains SERCA Ca2+-ATPase for calcium re-uptake. SR calcium concentration: ~1 mM; cytoplasmic resting calcium: ~0.1 µM."]','A','The SERCA pump (SERCA2a in cardiac, SERCA1 in fast skeletal) uses 2 ATP per 2 Ca2+ pumped. In heart failure, reduced SERCA2a expression impairs calcium re-uptake, prolonging contraction and elevating diastolic calcium — a therapeutic target (SERCA2a gene therapy in clinical trials).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Skeletal Muscle Structure','hard','flashcard','Compare the protein composition and function of nuclear bag fibres versus nuclear chain fibres in the muscle spindle.','["Nuclear bag fibres: large diameter, nuclei clustered centrally (bag). Dynamic bag1 fibres respond to velocity of stretch (Ia afferents). Static bag2 fibres respond to both velocity and sustained length (Ia + II afferents). Nuclear chain fibres: smaller, nuclei in a single row; respond to sustained length (mainly II afferents); show static response only."]','A','Dynamic γ-motor neurons preferentially innervate nuclear bag1 fibres; static γ-motor neurons innervate bag2 and chain fibres. This division allows independent control of dynamic and static spindle sensitivity, fine-tuning motor control.','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','easy','flashcard','Summarise the sliding filament theory of muscle contraction.','["Actin (thin) filaments slide over myosin (thick) filaments toward the M line, shortening the sarcomere. Filament lengths themselves do not change. Force is generated by repeated attachment, rotation (power stroke), and detachment of myosin cross-bridges on actin, driven by ATP hydrolysis."]','A','Proposed independently by A.F. Huxley and Niedergerke, and H.E. Huxley and Hanson in 1954. The theory explains the length-tension relationship and the constant A band length during contraction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','easy','flashcard','What is the sequence of events in excitation-contraction coupling in skeletal muscle?','["Motor neuron AP → ACh release → EPP → muscle AP → propagates along T-tubules → DHPR conformational change → mechanical opening of RyR1 → Ca2+ floods sarcoplasm → Ca2+ binds TnC → tropomyosin shifts → actin-myosin binding → cross-bridge cycling → contraction."]','A','This sequence takes <10 ms. The safety factor at the NMJ (EPP >> threshold) ensures reliable transmission. Calcium concentration in the sarcoplasm rises from ~0.1 µM (rest) to ~10 µM (peak contraction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','medium','flashcard','Describe the cross-bridge cycle in four steps.','["Step 1: ATP hydrolysis (ADP+Pi bound to myosin head) → cocked high-energy conformation. Step 2: Myosin head binds actin (weak binding with Pi). Step 3: Pi release → strong binding + power stroke (~10 nm actin movement). Step 4: ADP release → rigor state. New ATP binds → myosin detaches from actin → cycle repeats."]','A','Without ATP (rigor mortis or death), myosin remains in the rigor state permanently attached to actin. Each cross-bridge cycle is asynchronous — at any instant, ~50% of cross-bridges are attached during a tetanic contraction.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','medium','flashcard','Explain the length-tension relationship in skeletal muscle.','["At optimal length (sarcomere ~2.0-2.2 µm): maximum actin-myosin overlap → maximum cross-bridges → peak force. At shorter lengths: actin filaments overlap each other + myosin contacts Z disc → reduced force. At longer lengths: reduced actin-myosin overlap → fewer cross-bridges → reduced force."]','A','The length-tension relationship explains why muscles generate less force at very short or very long lengths. In vivo, joints keep muscles near optimal length. Eccentric exercise occurs on the descending limb of the curve, increasing passive titin-mediated force contribution.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','medium','flashcard','What is rigor mortis and what causes it?','["Rigor mortis is post-mortem muscular rigidity caused by ATP depletion. Without ATP, myosin heads cannot detach from actin after the power stroke, locking all cross-bridges in a rigor state. Onset: 2-6 hours (glycogen depletion → ATP falls); fully established: 12 hours; resolves 24-48 hours later due to autolytic enzyme degradation of contractile proteins."]','A','The resolution of rigor (passing off) occurs due to decomposition/autolysis — NOT because ATP is restored. In forensic pathology, the state of rigor mortis helps estimate time of death. Temperature and muscle activity before death affect the rate of rigor onset.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','hard','flashcard','Explain how malignant hyperthermia arises and how dantrolene treats it.','["Malignant hyperthermia (MH): triggered by volatile anaesthetics/succinylcholine in patients with RyR1 gain-of-function mutations. Uncontrolled Ca2+ release from SR → sustained muscle contraction → hyperthermia, acidosis, hyperkalaemia, rhabdomyolysis, DIC. Dantrolene directly blocks RyR1, reducing SR calcium release → breaks the cycle."]','A','MH susceptibility is autosomal dominant. Testing by in vitro contracture test (IVCT/CHCT) on muscle biopsy. Dantrolene must be given rapidly. Mortality without treatment >70%; with dantrolene <5%. Central core disease (another RyR1 mutation disorder) also confers MH susceptibility.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','hard','flashcard','Compare E-C coupling in skeletal versus cardiac muscle.','["Skeletal: DHPR directly (mechanically) opens RyR1 — no extracellular Ca2+ entry needed. Cardiac: DHPR (L-type Ca2+ channel) opens and Ca2+ influx through DHPR triggers RyR2 opening (calcium-induced calcium release, CICR) — requires extracellular calcium."]','A','This difference explains why skeletal muscle can contract in a calcium-free medium (isolated) while cardiac muscle cannot. In cardiac muscle, the amount of CICR (and thus contractile force) is graded by the amount of trigger Ca2+ entering through DHPR — the basis of the Frank-Starling relationship at the molecular level.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','easy','flashcard','What is the role of SERCA in muscle relaxation?','["SERCA (Sarcoplasmic/Endoplasmic Reticulum Calcium ATPase) actively pumps Ca2+ from the cytoplasm back into the SR lumen (2 Ca2+ per ATP hydrolysed), reducing cytoplasmic Ca2+ below the TnC binding threshold (~0.1 µM) → tropomyosin re-covers myosin binding sites → cross-bridge cycling stops → relaxation."]','A','SERCA is regulated by phospholamban (PLN) in cardiac and slow skeletal muscle — unphosphorylated PLN inhibits SERCA; β-adrenergic stimulation → PKA phosphorylates PLN → relieves inhibition → faster Ca2+ re-uptake → faster relaxation (lusitropic effect). Thapsigargin blocks SERCA.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','hard','flashcard','What is the force-velocity relationship in skeletal muscle and what is its physiological basis?','["As velocity of shortening increases, force decreases (Hill''''s equation: (P+a)(V+b) = (P0+a)b). At zero velocity (isometric), maximum force (P0). At maximum velocity (Vmax), force = 0. Physiological basis: at higher velocities, cross-bridges attach less often per unit time (less time for strong binding), generating less average force."]','A','Vmax depends on myosin heavy chain isoform (ATPase rate) — higher in type IIx than type I fibres. In eccentric contractions (muscle lengthening), force can exceed isometric P0 because cross-bridges are forcibly detached, generating more force — explaining why eccentric exercise causes more muscle damage.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Contraction Mechanism','medium','flashcard','How do calcium and the troponin-tropomyosin complex regulate actin-myosin interaction?','["At rest: TnI holds tropomyosin over the myosin-binding sites on actin (blocked state). Ca2+ rise → binds TnC → conformational change in TnI → releases tropomyosin → shifts to ''''closed'''' then ''''open'''' state exposing binding sites → myosin heads can bind actin → cross-bridge cycling."]','A','Three states of the thin filament: Blocked (no Ca2+, TnI engaged), Closed (Ca2+ bound, partial exposure), Open (full exposure with cross-bridge attached). Regulation is cooperative — binding of a few myosin heads can shift the thin filament to the open state along its length.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','easy','flashcard','Compare type I, type IIa, and type IIx skeletal muscle fibres across five characteristics.','["Type I: slow MHC, high oxidative, low glycolytic, red (high myoglobin), fatigue-resistant, small, low force, used for posture/endurance. Type IIa: fast MHC IIa, intermediate oxidative+glycolytic, red-pink, moderate fatigue resistance, moderate force. Type IIx: fast MHC IIx, low oxidative, high glycolytic, pale, fatigue rapidly, large, high force, sprinting/power."]','A','True type IIb fibres (fastest, most glycolytic) exist in rodents but not in adult human limb muscles, which have IIx as the fastest type. Fibre type can shift with training: endurance training recruits more IIa at the expense of IIx; detraining reverses this.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','easy','flashcard','State Henneman''''s size principle of motor unit recruitment.','["Motor units are recruited in order from smallest to largest: small, slow-twitch, fatigue-resistant type I units first (low threshold) → larger type IIa → largest type IIx last (highest threshold). This orderly recruitment provides smooth, graded force."]','A','Size principle reflects the lower input resistance and lower rheobase of smaller motor neurons (easier to depolarise). Derecruitment also occurs in reverse order. Exceptions exist: ballistic movements may recruit large units early via descending commands.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','medium','flashcard','Name four mechanisms contributing to peripheral muscle fatigue during high-intensity exercise.','["1) Inorganic phosphate (Pi) accumulation → impairs RyR calcium release and power stroke force; 2) Acidosis (H+ rise from ATP hydrolysis) → impairs SERCA, cross-bridge kinetics; 3) ADP accumulation → slows myosin ATPase; 4) Potassium accumulation extracellularly → impairs action potential generation in T-tubules."]','A','Lactic acidosis was historically blamed for fatigue; current evidence suggests H+ effects are modest at physiological temperatures. Pi is a major fatigue agent — it reduces Ca2+ release from SR and directly impairs power stroke force generation.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','medium','flashcard','What adaptations does endurance training produce in skeletal muscle?','["Increased mitochondrial density (mitochondrial biogenesis via PGC-1α), increased capillary density, increased myoglobin, increased oxidative enzyme activity (citrate synthase, succinate dehydrogenase), shift from IIx to IIa fibres, improved fatty acid oxidation capacity, increased glycogen storage."]','A','PGC-1α is activated by AMPK (energy sensor), calcium/calmodulin, and ROS. It co-activates NRF-1/NRF-2 and TFAM, driving mitochondrial biogenesis. This lowers the oxygen cost of submaximal exercise and raises the lactate threshold.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','medium','flashcard','What is muscle fibre type plasticity and what stimuli can cause it?','["Muscle fibre type is not fixed — fibres can shift their myosin heavy chain (MHC) isoform expression and metabolic profile in response to stimuli: endurance training shifts IIx→IIa→I; immobilisation/denervation shifts I→II; chronic electrical stimulation of fast muscle converts it to a slow phenotype; hyperthyroidism → fast isoforms; hypothyroidism → slow isoforms."]','A','The MHC isoform is the primary determinant of contractile speed (sets ATPase rate and cross-bridge cycling velocity). MHC transitions occur over weeks to months via altered transcriptional regulation of MHC genes. In disease (e.g., heart failure), fibre type shifts to faster, less efficient isoforms.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','hard','flashcard','Explain the metabolic basis of the ''''second wind'''' phenomenon in McArdle disease.','["McArdle disease (glycogen phosphorylase deficiency): muscle cannot break down glycogen. Initial exercise causes rapid fatigue and ischaemic pain. After ~8-10 min rest, cardiac output increases sufficiently to deliver more blood glucose and free fatty acids to muscles, which can use these substrates. This partially compensates, allowing continued activity at lower intensity — the ''''second wind''''."]','A','Diagnosis: non-ischaemic forearm exercise test (no lactate rise with normal ammonia rise). Confirmatory: muscle biopsy showing absent phosphorylase activity. Management: dietary carbohydrate before exercise, sucrose ingestion pre-exercise, aerobic training to increase oxidative capacity.','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','hard','flashcard','What is the molecular mechanism of resistance training-induced muscle hypertrophy?','["Mechanical load activates integrin/focal adhesion complexes and growth factor receptors (IGF-1R) → PI3K → PDK1 → Akt → mTORC1 → S6K1 and 4E-BP1 phosphorylation → increased ribosome biogenesis and mRNA translation initiation → net protein synthesis. Satellite cells activate (MyoD, myogenin) → proliferate and fuse to myofibres, adding myonuclei to support hypertrophy."]','A','mTORC1 also integrates amino acid availability (via Rag GTPases sensing leucine) and energy status (AMPK inhibits mTORC1 via TSC2). Myostatin (TGF-β family member) normally inhibits mTOR and satellite cell activation — loss-of-function mutations cause extreme muscular hypertrophy (''''double muscle'''' cattle).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','easy','flashcard','What causes delayed-onset muscle soreness (DOMS) and when does it peak?','["DOMS is caused primarily by eccentric exercise-induced micro-damage to sarcomeres and connective tissue, followed by an inflammatory response. Onset: 12-24 hours after exercise; peaks 24-72 hours; resolves 5-7 days. NOT caused by lactic acid (which clears within 1 hour)."]','A','DOMS features: tenderness, stiffness, swelling, reduced range of motion, and elevated serum CK (peaks 24-72 hours). The repeated bout effect means a second identical bout causes significantly less DOMS, attributed to sarcomere addition in series and connective tissue adaptation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','hard','flashcard','What is sarcopenia and what molecular mechanisms drive age-related muscle loss?','["Sarcopenia: age-related progressive loss of skeletal muscle mass and function, beginning ~age 40 at ~0.5-1%/year. Mechanisms: reduced satellite cell numbers and proliferative capacity; anabolic resistance (reduced response to amino acids and exercise via impaired mTOR/IGF-1 signalling); increased myostatin; elevated inflammatory cytokines (IL-6, TNF-α); denervation of fast fibres and reinnervation by slow motor neurons."]','A','Sarcopenia is associated with falls, fractures, disability, and mortality. Resistance training and adequate protein intake (1.2-1.6 g/kg/day, leucine-enriched) are the most effective interventions. Testosterone replacement reduces sarcopenia in hypogonadal men.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Muscle Fibre Types & Fatigue','medium','flashcard','Define tetanus in muscle physiology and distinguish between unfused and fused tetanus.','["Tetanus: sustained muscle contraction produced by high-frequency motor neuron stimulation where successive twitches fuse due to incomplete relaxation. Unfused (incomplete) tetanus: stimulus frequency allows partial relaxation between twitches — saw-tooth force trace. Fused (complete) tetanus: frequency high enough that force is smooth and maximal — typically >50 Hz in human muscle."]','A','Tetanic force is 3-5× greater than a single twitch force due to calcium summation (SR releases more Ca2+ with each AP before previous Ca2+ is fully re-sequestered). In vivo, voluntary muscle contractions are always partially tetanic; single twitches do not occur during normal movement.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','easy','flashcard','Describe the steps of synaptic transmission at the neuromuscular junction.','["1) AP arrives at motor nerve terminal → opens VGCCs (P/Q type) → Ca2+ influx; 2) Ca2+ binds synaptotagmin → SNARE complex zippers → ACh vesicle fuses → ~200-300 quanta of ACh released; 3) ACh binds postsynaptic nAChR → Na+/K+ current → EPP; 4) EPP exceeds threshold → muscle AP generated; 5) AChE in synaptic cleft rapidly hydrolyses ACh → choline re-uptake."]','A','The safety factor at the NMJ is ~5× (EPP generated is ~70 mV, threshold only ~15 mV above RMP). This ensures reliable neuromuscular transmission even when ACh stores are partially depleted.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','easy','flashcard','What is the pharmacology of the postsynaptic nicotinic ACh receptor at the NMJ?','["The NMJ nAChR is a pentameric ligand-gated cation channel (2α1, β1, δ, ε in adults). ACh must bind both α subunits to open the channel. Drugs: Agonists — succinylcholine (depolarising block), decamethonium. Competitive antagonists — vecuronium, rocuronium, pancuronium (non-depolarising NMBAs, reversed by neostigmine/sugammadex)."]','A','AChE inhibitors (neostigmine, pyridostigmine) reverse non-depolarising block by increasing ACh concentration. Sugammadex specifically encapsulates aminosteroidal NMBAs (rocuronium, vecuronium) for reversal. Succinylcholine block is NOT reversed by neostigmine and can be worsened by it.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','medium','flashcard','Distinguish myasthenia gravis from Lambert-Eaton myasthenic syndrome in terms of antibody target, clinical pattern, and electrophysiology.','["MG: anti-AChR (or anti-MuSK) antibodies → postsynaptic receptor loss → weakness worse with use (fatigable), ocular/bulbar predominant, associated with thymoma; repetitive nerve stimulation: decremental response. LEMS: anti-VGCC (P/Q type) antibodies → reduced presynaptic ACh release → proximal limb > ocular, improves with repetition, associated with SCLC; RNS: incremental response at high frequencies."]','A','MuSK-antibody MG is seronegative for AChR antibodies, presents with prominent facial and bulbar weakness, poorly responsive to pyridostigmine. In LEMS, autonomic dysfunction (dry mouth, constipation, erectile dysfunction) and depressed reflexes (potentiated post-exercise) are key distinguishing features.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','medium','flashcard','How does botulinum toxin produce its effects and what are its clinical uses?','["BTX cleaves SNARE proteins (serotype A/E: SNAP-25; B/D/F: VAMP/synaptobrevin; C: syntaxin + SNAP-25), preventing ACh vesicle fusion → flaccid paralysis of injected muscle. Clinical uses: focal dystonia (cervical dystonia, blepharospasm), spasticity, hyperhidrosis, chronic migraine, bladder overactivity, cosmetic wrinkle reduction."]','A','Recovery from BTX occurs over 3-4 months via axonal sprouting and formation of new NMJs, then retraction of sprouts as the original NMJ recovers. BTX-A (BOTOX, Dysport) is the most widely used. At lethal doses, BTX is the most toxic substance known (LD50 ~1-2 ng/kg).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','medium','flashcard','What is miniature end-plate potential (MEPP) and what does it represent?','["A MEPP is a tiny spontaneous depolarisation (~0.5-1 mV) at the NMJ caused by the spontaneous fusion of a single synaptic vesicle (1 quantum = ~5,000-10,000 ACh molecules) with the presynaptic membrane in the absence of a nerve action potential. MEPPs occur at ~1 Hz at each NMJ."]','A','MEPPs were described by Fatt and Katz (1952). A nerve action potential releases ~200-300 quanta simultaneously (quantal content = ~200). In botulinum toxin poisoning, MEPP frequency and quantal content are reduced. MEPP amplitude is reduced in MG (fewer functional receptors).','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','hard','flashcard','How does organophosphate toxicity present and what is the pharmacological treatment?','["Muscarinic (SLUDGE/DUMBELS): salivation, lacrimation, urination, defaecation, GI cramping/emesis; bronchospasm, bradycardia, miosis. Nicotinic: fasciculations, muscle weakness → paralysis; tachycardia, hypertension. CNS: seizures, coma. Treatment: 1) Atropine (large doses — muscarinic blockade); 2) Pralidoxime (2-PAM) — reactivates AChE before ''''ageing''''; 3) Benzodiazepines (seizures)."]','A','Ageing: permanent covalent bond between OP and AChE — pralidoxime must be given within hours before ageing occurs. Soman ages within minutes. Atropine only treats muscarinic symptoms; pralidoxime needed for the nicotinic/NMJ effects. N-methyl-D-aspartate receptor antagonism (memantine) may reduce CNS excitotoxicity.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','hard','flashcard','Describe the synthesis, storage, and degradation of acetylcholine at the motor nerve terminal.','["Synthesis: choline (from CHT1 reuptake) + acetyl-CoA (from mitochondria) → ACh, catalysed by choline acetyltransferase (ChAT) in nerve terminal cytoplasm. Storage: ACh packaged into synaptic vesicles via VAChT (vesicular ACh transporter) using H+ gradient. Degradation: AChE (in synaptic cleft, attached to basal lamina via ColQ) hydrolyses ACh → acetate + choline (choline recycled by CHT1)."]','A','Rate-limiting step for ACh synthesis = choline re-uptake via CHT1. Hemicholinium-3 blocks CHT1, depleting ACh. Vesamicol blocks VAChT. AChE is anchored to basal lamina by ColQ (collagen Q); mutations in ColQ cause a congenital myasthenic syndrome.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','easy','flashcard','What is the role of synaptotagmin at the NMJ?','["Synaptotagmin 1 is the calcium sensor on synaptic vesicles. When intraterminal Ca2+ rises (triggered by action potential opening VGCCs), Ca2+ binds to synaptotagmin''''s C2 domains, causing it to interact with the SNARE complex (SNAP-25, syntaxin, synaptobrevin) and the plasma membrane, triggering rapid, synchronous vesicle fusion and ACh exocytosis."]','A','Without synaptotagmin, spontaneous (asynchronous) release still occurs via SNARE proteins but synchronous fast release is abolished. Synaptotagmin C2 domains also bind phospholipids and Complexin (a SNARE clamp protein). Ca2+ influx through VGCCs must reach >100 µM locally at active zones to trigger release — the ''''Ca2+ microdomain'''' hypothesis.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','hard','flashcard','What are congenital myasthenic syndromes (CMS) and how do they differ from autoimmune myasthenia gravis?','["CMS are inherited disorders (AR or AD) of NMJ proteins: AChR subunit mutations (commonest), ColQ (AChE deficiency), DOK7 (required for MuSK signalling and end-plate development), RAPSN (AChR clustering), CHAT (ChAT deficiency). Seronegative for AChR/MuSK antibodies. Onset from birth. Not immunotherapy-responsive."]','A','DOK7 CMS presents with limb-girdle pattern weakness, responds to salbutamol (β2-agonist) rather than AChE inhibitors. CHAT deficiency: episodic apnoea, worsened by AChE inhibitors. Diagnosis by NMJ electrophysiology + genetic testing. Key distinction from autoimmune MG: genetic, present from birth, no antibodies, no thymoma.','universal',false,'{year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Neuromuscular Junction','medium','flashcard','What is a depolarising versus a non-depolarising neuromuscular block and how is each reversed?','["Depolarising block (succinylcholine/suxamethonium): acts as non-hydrolysable ACh agonist → sustained depolarisation → Na+ channel inactivation → flaccid paralysis. Phase I: not reversed by AChE inhibitors. Phase II (desensitisation): may partially respond. Non-depolarising block (rocuronium, vecuronium, atracurium): competitive nAChR antagonism. Reversed by: neostigmine/edrophonium (AChE inhibitors) or sugammadex (encapsulates aminosteroidal agents)."]','A','Sugammadex (modified γ-cyclodextrin) forms a tight 1:1 complex with rocuronium (highest affinity) and vecuronium, rapidly reducing free plasma drug and reversing block. No reversal agent exists for succinylcholine — rely on pseudocholinesterase (plasma cholinesterase) hydrolysis. Pseudocholinesterase deficiency → prolonged succinylcholine block.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','easy','flashcard','Classify joints by structural type and give an example of each.','["Fibrous: sutures (skull), syndesmoses (tibiofibular), gomphoses (tooth in socket). Cartilaginous: synchondroses (epiphyseal growth plate, 1st costochondral joint); symphyses (pubic symphysis, intervertebral discs). Synovial: most limb joints (shoulder, knee, hip, elbow) — have a joint cavity."]','A','Fibrous joints allow little/no movement (immovable = synarthroses). Synchondroses are temporary. Symphyses allow limited movement (amphiarthroses). Synovial joints are most mobile (diarthroses).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','easy','flashcard','Name the six types of synovial joint with an example of each.','["1) Hinge (ginglymus): elbow (humeroulnar), interphalangeal joints; 2) Pivot (trochoid): atlantoaxial (C1-C2), proximal radioulnar; 3) Ball-and-socket (spheroid): hip, shoulder; 4) Condyloid (ellipsoid): wrist (radiocarpal), MCP joints; 5) Saddle (sellar): 1st carpometacarpal (thumb); 6) Plane (gliding): acromioclavicular, intercarpal, subtalar."]','A','Ball-and-socket joints allow triaxial movement (flexion/extension, abduction/adduction, rotation). Saddle joints allow biaxial movement. Hinge and pivot joints are uniaxial. Plane joints allow translational gliding. The type of movement is constrained by joint shape and ligamentous arrangement.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','medium','flashcard','What are the components of a synovial joint and the function of each?','["1) Articular cartilage (hyaline): reduces friction, absorbs shock; 2) Synovial membrane (inner capsule): produces synovial fluid; 3) Synovial fluid: lubrication + nutrition of cartilage; 4) Joint capsule (fibrous): containment and stability; 5) Ligaments: passive stability; 6) Intra-articular structures (menisci, fat pads, labra): congruency, load distribution."]','A','Articular cartilage has no perichondrium, is avascular, aneural, and alymphatic — explaining its poor intrinsic repair capacity. The lack of nerve supply explains why advanced OA pain arises from subchondral bone, osteophytes, and synovitis rather than cartilage itself.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','medium','flashcard','What is the composition of synovial fluid and what does it reveal in different joint diseases?','["Normal: clear, viscous, few WBCs (<200 cells/µL, mainly mononuclear), glucose ~ serum, high hyaluronic acid concentration. Non-inflammatory (OA): slightly turbid, <2,000 WBC/µL. Inflammatory (RA): turbid, 2,000-50,000 WBC/µL (mainly PMNs). Septic: purulent, >50,000 WBC/µL, low glucose, positive culture. Crystal: variable WBC, crystals on polarised light microscopy."]','A','The WBC count in synovial fluid is used to classify effusions: <2,000 non-inflammatory (OA, trauma); 2,000-50,000 inflammatory (RA, gout, reactive arthritis); >50,000 (often >100,000) suggests septic arthritis requiring urgent antibiotics and washout.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','medium','flashcard','What stabilises the hip joint?','["Static: acetabular depth (deepened by labrum), capsular ligaments (iliofemoral/Y-ligament of Bigelow — strongest in body; ischiofemoral; pubofemoral), ligamentum teres (weak), negative intra-articular pressure. Dynamic: hip abductors (gluteus medius, minimus), iliopsoas, short external rotators (piriformis, obturators, gemelli, quadratus femoris)."]','A','The Y-ligament (iliofemoral) prevents hyperextension of the hip in standing. Gluteus medius is critical for maintaining pelvic stability during single-leg stance (Trendelenburg sign when weak/denervated — L4/5, superior gluteal nerve). Hip dislocation is most commonly posterior (forced adduction + internal rotation).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','hard','flashcard','Describe the mechanisms of lubrication in synovial joints.','["1) Hydrodynamic lubrication: fluid film separates surfaces at high speed (walking). 2) Boundary lubrication: lubricin (PRG4) and hyaluronic acid form a monomolecular layer at the cartilage surface, preventing direct contact at low speeds/high loads. 3) Squeeze-film lubrication: fluid is expressed from cartilage under load, maintaining a film. 4) Weeping lubrication: fluid re-enters cartilage when load is removed."]','A','Lubricin (PRG4) is secreted by type B synoviocytes and superficial chondrocytes. Mutations in PRG4 cause camptodactyly-arthropathy-coxa vara-pericarditis (CACP) syndrome, characterised by joint failure due to absent boundary lubrication.','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','hard','flashcard','Compare the pathophysiology of osteoarthritis and rheumatoid arthritis.','["OA: non-inflammatory mechanical degeneration — cartilage breakdown (MMP/ADAMTS activation by chondrocytes, repetitive loading, ageing), subchondral sclerosis, osteophyte formation; no systemic features; DIP, PIP, 1st CMC, hip, knee affected; Heberden''''s and Bouchard''''s nodes. RA: autoimmune synovitis (anti-CCP, RF, anti-AChR-V antibodies) → pannus → cartilage/bone erosion; systemic inflammation; MCP, PIP, wrist affected (spares DIP); extra-articular features."]','A','Key radiographic differences: OA — joint space narrowing, osteophytes, subchondral sclerosis, no erosions. RA — joint space narrowing, erosions (periarticular), periarticular osteoporosis, no osteophytes. Deformities in RA: ulnar deviation at MCPs, swan-neck, boutonnière, Z-thumb.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','easy','flashcard','What is the function of intra-articular menisci in the knee?','["Medial and lateral fibrocartilage menisci: 1) Increase joint congruency, distributing load over a larger area (reduces contact pressure by ~50%); 2) Act as shock absorbers; 3) Contribute to joint stability; 4) Assist in joint lubrication; 5) Aid proprioception (nerve endings in peripheral third)."]','A','The peripheral third of the meniscus is vascularised (red zone — can heal spontaneously); the inner two-thirds are avascular (white zone — poor healing). Meniscectomy increases contact pressure → accelerates cartilage degeneration → OA. Meniscus repair/transplant preferred over removal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','hard','flashcard','Explain the clinical significance and mechanism of the pivot shift test in ACL rupture.','["In ACL-deficient knees, the anterolateral soft tissue complex (ALL, IT band) and ACL normally prevent internal rotation and anterior translation of the tibia. Pivot shift test: knee extended, internally rotated, valgus force applied → tibia subluxes anteriorly (reduced by IT band acting as flexor). At ~30° flexion, IT band crosses the joint line (switches from extensor to flexor moment arm) → sudden reduction of subluxation — felt as a ''''clunk''''."]','A','The pivot shift is the most functionally relevant ACL test (corresponds to instability during sports). Sensitivity alone ~40%; specificity ~99%. Graded 0-3+ (0 = none, 3+ = gross subluxation). A positive pivot shift predicts functional instability and secondary meniscal/cartilage injury risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Joint Anatomy','medium','flashcard','What is the difference between a primary and secondary stabiliser of the shoulder?','["Primary stabilisers (static): glenohumeral labrum (deepens socket), glenohumeral ligaments (SGHL, MGHL, IGHL complex), negative intra-articular pressure, articular congruity. Secondary (dynamic): rotator cuff muscles (SITS: supraspinatus, infraspinatus, teres minor, subscapularis) compress the humeral head into the glenoid; deltoid, biceps long head."]','A','The IGHL (inferior glenohumeral ligament) is the primary static stabiliser against anterior dislocation (the most common direction). Rotator cuff tear reduces dynamic stability, increasing dependence on static stabilisers and predisposing to secondary OA. Bankart lesion = detachment of IGHL and labrum from glenoid rim in anterior dislocation.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','easy','flashcard','What are the four types of proprioceptors in muscle and tendon, and what does each detect?','["1) Muscle spindle primary endings (Ia): velocity and length of muscle stretch. 2) Muscle spindle secondary endings (II): static muscle length. 3) Golgi tendon organs (Ib): tension in the tendon (active and passive). 4) Joint mechanoreceptors (Ruffini/Pacinian in capsule): joint angle, acceleration, vibration."]','A','Group Ia fibres are the fastest conducting (70-120 m/s) — critical for rapid stretch reflexes. Group Ib fibres: 70-120 m/s. Group II: 30-70 m/s. Groups III and IV (thin myelinated/unmyelinated): metabolites, pain, temperature during exercise.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','easy','flashcard','Describe the monosynaptic stretch reflex arc (e.g., patellar reflex).','["Tap patellar tendon → stretches quadriceps → Ia afferents from quadriceps spindles → enter spinal cord (L3/L4) → monosynaptic excitation of L3/L4 quadriceps α motor neurons → quadriceps contraction. Simultaneously, Ia inhibitory interneurons inhibit hamstring α motor neurons (reciprocal inhibition)."]','A','The stretch reflex is the only truly monosynaptic reflex in the CNS (only one synapse between afferent and efferent neuron). It is used clinically to assess segmental spinal cord function. Hyperreflexia indicates upper motor neuron lesion; hyporeflexia indicates lower motor neuron or afferent lesion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','medium','flashcard','Explain the purpose of alpha-gamma coactivation during voluntary movement.','["When voluntary movement is initiated, the motor cortex simultaneously activates α motor neurons (causing extrafusal fibre contraction) and γ motor neurons (causing intrafusal fibre contraction via their polar regions). This coactivation prevents the spindle from going slack as the muscle shortens, maintaining spindle sensitivity throughout the movement for ongoing position monitoring and reflex modulation."]','A','Without γ coactivation, muscle spindles would be unloaded during contraction and unable to detect perturbations or length changes. In Parkinson''''s disease, γ motor neuron overactivity (due to loss of dopamine and reduced descending inhibition) contributes to rigidity and the ''''cogwheel'''' phenomenon.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','medium','flashcard','Describe the hierarchical structure of a tendon from molecule to whole structure.','["Tropocollagen (triple helix, 300 nm long, 1.5 nm diameter) → microfibrils (5 tropocollagen molecules in a quarter-staggered array) → fibrils (10-500 nm diameter, with D-banding at 67 nm) → fascicles (primary, secondary, tertiary bundles surrounded by endotenon) → whole tendon (surrounded by epitenon/paratenon). The crimp pattern (waviness of fibrils) provides a toe region of elasticity."]','A','The characteristic crimp (wavy pattern of collagen fibrils) allows a small amount of elasticity at low loads (toe region of stress-strain curve), protecting from sudden overload. Beyond the toe region, linear elastic behaviour until failure. Crimps are lost with age or injury.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','medium','flashcard','What is the autogenic (inverse myotatic) inhibition reflex and what is its protective function?','["High tension in the tendon activates Golgi tendon organ (GTO) Ib afferents → enter spinal cord → synapse on inhibitory Ib interneurons → inhibit homonymous α motor neurons (reducing muscle force) → excite antagonist motor neurons. This autogenic inhibition protects against excessive tendon tension that could cause rupture."]','A','The clasp-knife response in upper motor neuron lesions (spasticity): initial high resistance to passive stretch (due to abnormal tonic stretch reflex) followed by sudden give (collapse) — the ''''clasp-knife'''' phenomenon — attributed to Ib autogenic inhibition overriding the hyper-excitable stretch reflex at high muscle tensions.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','hard','flashcard','Compare tendon and ligament in terms of composition, structure, vascularity, and healing capacity.','["Tendon: >95% type I collagen, highly parallel arrangement, higher collagen:ground substance ratio, higher tensile strength, wrapped in paratenon/endotenon, moderate vascularity (from musculotendinous junction, tendon-bone junction, and surrounding paratenon). Ligament: mainly type I collagen but less organised (multidirectional loading), more elastin, similar vascularity. Both heal slowly (dense connective tissue)."]','A','Tendon healing occurs in three phases: Inflammatory (0-1 week), Proliferative (1-6 weeks: fibroblasts deposit disorganised type III collagen), Remodelling (6 weeks-2 years: type I collagen replaces III, fibres align). Final tendon is mechanically inferior to original (higher collagen III content, less crimp). Peritendinous adhesions can limit gliding.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','hard','flashcard','What are the three zones of the enthesis (tendon-bone insertion) and why is enthesitis important?','["Zone 1: Pure tendon (parallel collagen type I fibres). Zone 2: Fibrocartilage (uncalcified — chondrocytes, type II collagen). Zone 3: Calcified fibrocartilage (mineralised, type X collagen). Zone 4: Bone (subchondral). This gradient dissipates stress concentration at the hard-soft tissue interface."]','A','Enthesitis (inflammation at the enthesis) is a hallmark of seronegative spondyloarthropathies (ankylosing spondylitis, psoriatic arthritis, reactive arthritis). The Achilles enthesis and plantar fascia insertion are classic sites. The pathological process involves immunological attack at the enthesis, leading to erosion and later new bone formation (syndesmophytes, spurs).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','easy','flashcard','What is proprioception and why is it clinically important?','["Proprioception is the sense of the position, movement, and force of the body and limbs in space, derived from muscle spindles, GTOs, joint mechanoreceptors, and skin receptors. Clinically important because: 1) ACL/ankle ligament injuries impair proprioception → instability; 2) Diabetic peripheral neuropathy impairs proprioception → falls; 3) Cerebellar and dorsal column lesions impair proprioception → ataxia."]','A','The Romberg test assesses proprioception — patients with dorsal column lesions (tabes dorsalis, vitamin B12 deficiency) can maintain balance with eyes open (using visual compensation) but fall when eyes are closed. Proprioceptive rehabilitation (balance training) is essential after joint ligament injury.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','hard','flashcard','What is the difference between dynamic and static nuclear bag fibres in the muscle spindle?','["Dynamic nuclear bag 1 (bag1) fibres: innervated by dynamic γ motor neurons; respond powerfully to velocity of stretch (dynamic phase response) via primary Ia endings; adapt quickly to sustained stretch. Static nuclear bag 2 (bag2) and nuclear chain fibres: innervated by static γ motor neurons; maintain response to sustained length (static response via both Ia and II endings)."]','A','The distinction allows the CNS to independently control sensitivity to movement (dynamic response, bag1) versus steady-state length (static response, bag2/chain). In Parkinson''''s disease, γ motor neuron bias toward dynamic response contributes to the ''''lead pipe'''' rigidity (not true spasticity — no velocity dependence lost).','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Tendons, Ligaments & Proprioception','medium','flashcard','Describe the mechanism and clinical significance of the Jendrassik manoeuvre.','["The Jendrassik manoeuvre (interlocking fingers and pulling them apart) reinforces deep tendon reflexes in patients with apparently absent or reduced reflexes. Mechanism: the voluntary isometric effort in the upper limbs increases γ motor neuron activity (supraspinal facilitation of the reticular system) → greater intrafusal tension → lower threshold for Ia firing → enhanced reflex arc."]','A','Used clinically to unmask hypo- or areflexia versus genuine reflex absence. A response to Jendrassik reinforcement suggests the lower motor neuron arc is intact and the reduced reflex is due to pre-synaptic inhibition or hypofacilitation (upper motor neuron or descending pathway issue), rather than LMN damage.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','easy','flashcard','Summarise the metabolic activation pathway of vitamin D.','["Skin: 7-dehydrocholesterol + UV-B → cholecalciferol (vitamin D3). Liver: CYP2R1/CYP27A1 → 25-hydroxyvitamin D3 (calcidiol, 25(OH)D — the main circulating form, measured clinically). Kidney (proximal tubule): CYP27B1 (1α-hydroxylase) → 1,25-dihydroxyvitamin D3 (calcitriol, the active form). Inactivation: CYP24A1 (24-hydroxylase) → 24,25(OH)2D3."]','A','25(OH)D is the marker measured clinically to assess vitamin D status (normal: >50 nmol/L, insufficiency: 25-50 nmol/L, deficiency: <25 nmol/L). 1,25(OH)2D3 is the active hormone but its serum level is not a reliable indicator of vitamin D stores. 1α-hydroxylase is induced by PTH, hypocalcaemia, and hypophosphataemia.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','easy','flashcard','What are the three target organs of PTH and calcitriol, and their effects on each?','["PTH: Bone — increased resorption (via RANKL on osteoblasts); Kidney — increased Ca reabsorption (DCT), increased phosphate excretion (PCT), stimulates 1α-hydroxylase; Intestine — indirect (via calcitriol). Calcitriol: Intestine — increases TRPV6, calbindin-D, Ca-ATPase (major site of action); Kidney — increases Ca and P reabsorption; Bone — promotes mineralisation and calcium mobilisation."]','A','PTH acts rapidly (minutes) via cAMP/PKA; calcitriol acts via nuclear VDR (hours to days). Both elevate serum calcium. PTH lowers phosphate; calcitriol raises it. Calcitonin (parafollicular C cells) opposes PTH by inhibiting osteoclasts and promoting renal calcium excretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','medium','flashcard','Explain the calcium-sensing receptor (CaSR) and its role in calcium homeostasis.','["The CaSR (G protein-coupled receptor on parathyroid chief cells and renal tubular cells) detects the extracellular ionised calcium concentration. When Ca2+ rises → CaSR activates Gq/Gi → reduces PTH secretion and synthesis; increases renal calcium excretion. When Ca2+ falls → reduced CaSR activation → PTH secretion increases."]','A','CaSR mutations: activating = autosomal dominant hypocalcaemia (ADH, mimics hypoparathyroidism); loss-of-function heterozygous = familial hypocalciuric hypercalcaemia (FHH, high calcium but low urinary calcium, usually asymptomatic); homozygous loss-of-function = neonatal severe hyperparathyroidism. Cinacalcet is a CaSR allosteric activator (calcimimetic) used in hyperparathyroidism.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','medium','flashcard','What biochemical findings would you expect in primary, secondary, and tertiary hyperparathyroidism?','["Primary (adenoma/hyperplasia): ↑PTH, ↑Ca, ↓PO4, ↑urine Ca, ↑calcitriol. Secondary (CKD/vitamin D deficiency): ↑PTH (reactive), ↓Ca, ↑PO4 (CKD), ↓calcitriol. Tertiary (longstanding secondary → autonomous PTH secretion): ↑PTH, ↑Ca (hypercalcaemia despite correction of primary cause), ↑PO4 (if CKD persists)."]','A','CKD-MBD management: dietary phosphate restriction, phosphate binders, active vitamin D supplements (alfacalcidol), cinacalcet. Parathyroidectomy for refractory tertiary hyperparathyroidism. Osteitis fibrosa cystica = severe primary hyperparathyroidism: subperiosteal resorption on radial border of 2nd finger (X-ray), brown tumours, pepper-pot skull.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','medium','flashcard','What is the clinical triad of symptoms in hypercalcaemia and the four main causes?','["''''Bones, stones, abdominal groans, and psychic moans'''': bone pain/fractures, nephrolithiasis (calcium oxalate/phosphate), nausea/constipation/pancreatitis, depression/confusion. Four main causes: 1) Primary hyperparathyroidism (most common outpatient); 2) Malignancy (most common inpatient — PTHrP, osteolytic mets); 3) Sarcoidosis/granulomas (macrophage 1α-hydroxylase); 4) Vitamin D intoxication."]','A','ECG in hypercalcaemia: shortened QT interval (calcium shortens phase 2 of cardiac AP). Treatment of severe hypercalcaemia (>3.5 mmol/L): IV saline hydration, bisphosphonates (zoledronate), denosumab, calcitonin (short-term), steroids (granulomas), dialysis (severe renal failure).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','hard','flashcard','Explain FGF-23 and its role in phosphate homeostasis.','["FGF-23 is secreted by osteocytes in response to high serum phosphate, high calcitriol, and PTH. It requires the co-receptor Klotho. Actions: 1) Inhibits NaPi-IIa/IIc in proximal tubule → phosphaturia; 2) Inhibits CYP27B1 (1α-hydroxylase) and stimulates CYP24A1 → reduces calcitriol → reduces intestinal phosphate absorption."]','A','Excess FGF-23 (X-linked hypophosphataemia/XLH from PHEX mutations; autosomal dominant/recessive hypophosphataemia): phosphate wasting → rickets/osteomalacia. Tumour-induced osteomalacia: FGF-23-secreting mesenchymal tumours. Treatment: burosumab (anti-FGF-23 antibody) for XLH. FGF-23 rises early in CKD and contributes to cardiovascular disease (left ventricular hypertrophy).','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','hard','flashcard','Describe the mechanism and clinical features of hypoparathyroidism.','["PTH deficiency → low serum Ca (reduced bone resorption, reduced DCT Ca reabsorption, reduced calcitriol) + high serum phosphate (reduced urinary phosphate excretion) + low urinary calcium. Clinical features: tetany (Chvostek''''s sign — facial muscle twitch on cheek tap; Trousseau''''s sign — carpal spasm during BP cuff inflation), paraesthesias, seizures, prolonged QT, basal ganglia calcification (long-term), cataracts."]','A','Most common cause: post-thyroidectomy (accidental parathyroid removal or devascularisation). Other causes: autoimmune (APS type 1 — AIRE mutations), DiGeorge syndrome (22q11 deletion), hypomagnesaemia (impairs PTH release/action). Treatment: calcium supplements + active vitamin D (alfacalcidol/calcitriol). Newer: rhPTH1-84 (Natpara) replacement therapy.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','easy','flashcard','What is the difference between osteoporosis, osteomalacia, and osteitis fibrosa cystica?','["Osteoporosis: reduced bone QUANTITY (normal mineralisation, reduced mass — T-score < −2.5). Osteomalacia (adults)/rickets (children): reduced bone QUALITY — insufficient mineralisation of normal osteoid quantity due to vitamin D deficiency or hypophosphataemia; soft bones. Osteitis fibrosa cystica: excessive bone resorption from hyperparathyroidism → fibrous replacement of marrow, brown tumours, subperiosteal resorption."]','A','Biochemistry: Osteoporosis — usually normal Ca, PO4, ALP, PTH. Osteomalacia — low Ca, low PO4, raised ALP, raised PTH (secondary). Osteitis fibrosa cystica — raised Ca, low PO4, very high ALP, very high PTH. Bone biopsy: osteoporosis → thin but mineralised trabeculae; osteomalacia → wide unmineralised osteoid seams.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','hard','flashcard','How does magnesium deficiency cause hypoparathyroidism and hypocalcaemia?','["Severe hypomagnesaemia (<0.4 mmol/L): 1) Impairs PTH secretion (magnesium required for the fusion of PTH-containing secretory granules with the cell membrane); 2) Causes end-organ resistance to PTH (Mg needed for PTH receptor-G protein coupling). Result: PTH paradoxically low despite hypocalcaemia, and tissues do not respond normally even to exogenous PTH."]','A','Key clinical point: hypocalcaemia in the setting of hypomagnesaemia will NOT be corrected by calcium supplementation alone — magnesium must be replaced first. Causes of hypomagnesaemia: alcoholism, PPI use (impairs intestinal Mg absorption), loop/thiazide diuretics, cisplatin, malabsorption, diarrhoea.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Bone Metabolism & Calcium Regulation','medium','flashcard','What are the effects of calcitonin and when is it clinically used?','["Calcitonin (from thyroid C cells): rapidly inhibits osteoclast activity (via calcitonin receptors on osteoclasts) → reduces bone resorption and lowers serum calcium. Also promotes renal Ca and P excretion. Physiological importance in humans is debated (patients post-thyroidectomy maintain normal calcium). Clinical uses: acute hypercalcaemia (adjunctive, tachyphylaxis limits use >48h), Paget''''s disease, osteoporosis (nasal calcitonin — analgesic benefit in acute vertebral fractures)."]','A','Tachyphylaxis to calcitonin develops rapidly due to downregulation of calcitonin receptors on osteoclasts. Therefore, it is not used as a long-term treatment. Bisphosphonates or denosumab are preferred for sustained osteoclast inhibition.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','easy','flashcard','Define VO2max and explain what determines it.','["VO2max (maximal oxygen consumption) is the maximum rate at which the body can consume oxygen during maximal exercise. Determined by the Fick equation: VO2max = CO_max × (CaO2 − CvO2). Primarily limited by maximum cardiac output (HR × SV). Average: ~35 mL/kg/min (untrained); >70 mL/kg/min (elite endurance athletes)."]','A','Central factors (cardiac output) are the primary limitation in most individuals. Peripheral factors (capillary density, mitochondrial density, oxygen diffusion) can become limiting with targeted training. Altitude reduces VO2max by reducing inspired PO2 (FiO2 unchanged but PO2 falls with barometric pressure).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','easy','flashcard','What energy systems are used during exercise and over what time frames?','["0-10 seconds: Phosphagen (ATP-PCr) — immediate, anaerobic, no lactate. 10 seconds to 2 minutes: Anaerobic glycolysis (fast glycolysis) — rapid ATP from glucose, produces lactate. >2 minutes: Aerobic oxidative phosphorylation — glucose, fat, (protein) via TCA cycle/ETC — slower but unlimited capacity."]','A','In practice, all three systems contribute simultaneously; the proportion depends on intensity and duration. During maximal sprint: ~50% PCr, ~40% glycolysis, ~10% aerobic. During marathon: ~98% aerobic. Creatine supplementation increases PCr stores, improving high-intensity, short-duration performance by ~5-15%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','medium','flashcard','What are the cardiovascular adaptations to chronic endurance training?','["Resting bradycardia (increased vagal tone, reduced intrinsic heart rate), increased stroke volume (eccentric LV hypertrophy — increased cavity volume + wall thickness; increased plasma volume; improved diastolic filling), higher VO2max, increased arteriovenous O2 difference, enhanced capillary density in muscle, increased blood volume/red cell mass, decreased peripheral vascular resistance."]','A','Athlete''''s bradycardia: resting HR as low as 30-40 bpm in elite endurance athletes. The large resting stroke volume maintains adequate CO. On ECG: sinus bradycardia, sinus arrhythmia, 1st degree AV block, early repolarisation — all normal variants in athletes. Must be distinguished from pathological bradyarrhythmias.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','medium','flashcard','Explain the Fick principle as applied to oxygen consumption during exercise.','["Fick principle: VO2 = Cardiac Output × (CaO2 - CvO2). CaO2 = arterial O2 content (~200 mL/L); CvO2 = venous O2 content (rest ~150 mL/L, exercise ~20-50 mL/L). At rest: VO2 = 5 L/min × 50 mL O2/L = 250 mL O2/min. At maximal exercise (elite): VO2max = 25 L/min × 150 mL O2/L = 3750 mL O2/min = 53 mL/kg/min."]','A','The arteriovenous O2 difference widens during exercise because working muscles extract more oxygen (CvO2 falls). The mixed venous O2 content is measured from the pulmonary artery (right heart catheterisation). The Fick method is the gold standard for measuring cardiac output.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','medium','flashcard','What is the lactate threshold and how is it measured?','["The lactate threshold (LT1) is the exercise intensity at which blood lactate begins to rise above resting baseline (~2 mmol/L). LT2 (OBLA — onset of blood lactate accumulation) is when blood lactate reaches 4 mmol/L. Both are expressed as % VO2max or as running pace/power. Measured by incremental exercise test with serial blood lactate samples."]','A','Elite marathoners can sustain near their LT2 for >2 hours. Training raises the lactate threshold as a % VO2max (increased mitochondria → more oxidative disposal of pyruvate → less lactate production). Practical measurement: 3-4 min stages, serial earlobe/fingertip blood samples, plot lactate vs. intensity.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','hard','flashcard','Describe the molecular signalling cascade initiated by a single bout of endurance exercise.','["Exercise → ↑AMP:ATP ratio → activates AMPK → phosphorylates ACC (inhibits fat synthesis, promotes fat oxidation), activates PGC-1α. Ca2+/CaM-dependent pathways (CAMKII) also activate PGC-1α. PGC-1α translocates to nucleus → co-activates NRF-1/2 → drives TFAM → mitochondrial biogenesis; upregulates GLUT4, VEGF (angiogenesis), myoglobin. ROS from exercise also contribute to PGC-1α activation."]','A','AMPK is the master energy sensor (activated when AMP:ATP rises). It promotes catabolic processes (fat oxidation, glucose uptake via GLUT4 translocation) and inhibits anabolic processes (protein synthesis via mTOR inhibition). AMPK and mTOR are reciprocally regulated — explaining why combined endurance + resistance training may blunt hypertrophy (AMPK inhibits mTOR).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','hard','flashcard','What is overtraining syndrome and what are its physiological hallmarks?','["Overtraining syndrome (OTS, burnout): prolonged performance decrements (>2 months) despite reduced training, not attributable to illness or other disease. Features: persistent fatigue, mood disturbance, reduced VO2max, elevated resting HR, hormonal disruption (low testosterone:cortisol ratio, HPA axis dysregulation), immune suppression (open window theory — transient immunosuppression post-exercise), recurrent infections."]','A','Biomarkers for OTS are unreliable (no single diagnostic test). CK, urea, ferritin, cortisol, and testosterone:cortisol ratio are tracked longitudinally. Heart rate variability (HRV) monitoring is increasingly used. Treatment: relative rest, caloric sufficiency, psychological support. Prevention: periodised training with adequate recovery.','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','hard','flashcard','Explain the relative energy deficiency in sport (RED-S) syndrome and its musculoskeletal consequences.','["RED-S (formerly female athlete triad): relative energy deficiency = energy intake < energy expenditure, causing low energy availability (LEA). Hormonal consequences: suppressed hypothalamic GnRH → low LH/FSH → hypogonadism (female: amenorrhoea; male: low testosterone) + low IGF-1 + high cortisol. MSK consequences: reduced bone mineralisation → low BMD, stress fractures, impaired muscle protein synthesis → increased injury risk."]','A','RED-S affects both sexes. The triad (low energy availability, menstrual dysfunction, low BMD) was the original female version. Management: increase energy intake, reduce training load, address eating disorders, calcium/vitamin D supplementation. Bone loss may be irreversible if prolonged. Stress fractures are the key MSK presentation (femoral neck, tibia, metatarsals).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','easy','flashcard','What is muscle cramp and what are the proposed mechanisms?','["Muscle cramp is an involuntary, painful, sustained muscle contraction during or after exercise. Proposed mechanisms: 1) Neuromuscular fatigue hypothesis: sustained α motor neuron firing due to fatigue, spindle hyperexcitability, and reduced GTO inhibition; 2) Dehydration/electrolyte disturbance (Na+, Mg2+, K+ loss) — reduces threshold for spontaneous motor neuron discharge."]','A','Current evidence favours the neuromuscular mechanism over simple dehydration/electrolyte depletion. Pickleball/stretching reduces cramp risk by activating GTO inhibitory reflexes. Quinine was historically used but is now avoided (risk of QT prolongation/thrombocytopenia). Acute treatment: passive stretching, hydration, electrolyte replacement.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Anatomy & Physiology','Exercise Physiology & MSK Adaptations','medium','flashcard','What adaptations does resistance training produce in bone?','["Resistance training increases bone mineral density (BMD) via Wolff''''s law — mechanical loading stimulates osteocytes (via focal adhesion kinases and ion channels sensing fluid flow in canaliculi) → Wnt signalling → osteoblast activation → increased bone formation. Greatest effects at loaded sites (lumbar spine, femoral neck). Reduces fracture risk in osteoporosis. Also improves muscle-bone cross-sectional area ratio."]','A','Osteocytes are the primary mechanosensors: they respond to fluid shear stress in canaliculi induced by bone deformation during loading. They suppress sclerostin → activates Wnt → osteoblast activity. Vibration therapy mimics some mechanical loading benefits in populations unable to exercise.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');